arguments.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# The query key must be valid for a Cirrus Function URL (A-Z a-z 0-9 _ . -).
bash bin/render event | grep -o 'action="[^"]*"' | grep -q 'action="?action=[A-Za-z0-9_.-]*"' || { echo "render key"; fail=1; }
bash bin/render event | grep -o 'action="?[^"=]*' | grep -q '[^A-Za-z0-9_.?"=-]' && { echo "invalid key chars"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail
EOF
bash tests/forms_test.sh; echo "before:$?"
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must only use A-Z a-z 0-9 _ . - (Cirrus Function URL rejects other keys with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーは英数字と _ . - のみ。Function URL は他の文字のキーを 400 で拒否する）|' docs/framework.md
bash scripts/verify.sh; echo $?; bash bin/render event; git diff docs

